import{_ as e,c as t,o as a,a0 as n}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Sjabloon voor een trainingsdagboek","description":"","frontmatter":{},"headers":[],"relativePath":"nl/diary-template.md","filePath":"nl/diary-template.md"}');const r=e({name:"nl/diary-template.md"},[["render",function(e,i,r,o,l,s){return a(),t("div",null,[...i[0]||(i[0]=[n('<h1 id="sjabloon-voor-een-trainingsdagboek" tabindex="-1">Sjabloon voor een trainingsdagboek <a class="header-anchor" href="#sjabloon-voor-een-trainingsdagboek" aria-label="Permalink to &quot;Sjabloon voor een trainingsdagboek&quot;">​</a></h1><h2 id="hoe-gebruik-je-deze-sjabloon" tabindex="-1">Hoe gebruik je deze sjabloon? <a class="header-anchor" href="#hoe-gebruik-je-deze-sjabloon" aria-label="Permalink to &quot;Hoe gebruik je deze sjabloon?&quot;">​</a></h2><p>Een trainingsdagboek is je persoonlijke verslag van je oefeningen, vooruitgang en inzichten. Het helpt je bij te houden wat werkt, patronen te herkennen en je verbetering te versnellen. Kopieer de onderstaande secties naar het formaat van je voorkeur (Word, Google Docs, Excel, Google Sheets of een notitieboek).</p><div class="tip custom-block"><p class="custom-block-title">De kracht van reflectie</p><p><strong>Wat gemeten wordt, wordt verbeterd. Waarop gereflecteerd wordt, wordt beheerst.</strong> Een trainingsdagboek transformeert willekeurige oefening in doelgerichte ontwikkeling.</p></div><h2 id="sjabloon-voor-dagelijkse-trainingsregistratie" tabindex="-1">Sjabloon voor dagelijkse trainingsregistratie <a class="header-anchor" href="#sjabloon-voor-dagelijkse-trainingsregistratie" aria-label="Permalink to &quot;Sjabloon voor dagelijkse trainingsregistratie&quot;">​</a></h2><h3 id="kopieer-dit-gedeelte-voor-elke-trainingssessie" tabindex="-1">Kopieer dit gedeelte voor elke trainingssessie <a class="header-anchor" href="#kopieer-dit-gedeelte-voor-elke-trainingssessie" aria-label="Permalink to &quot;Kopieer dit gedeelte voor elke trainingssessie&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Time:</strong> ________ to ________ <strong>Duration:</strong> ________ minutes <strong>Location:</strong> ________ <strong>Terrain:</strong> Hard / Medium / Soft / Mixed <strong>Weather:</strong> Sunny / Cloudy / Windy / Rain</p><h3 id="training-partners" tabindex="-1">Training Partners <a class="header-anchor" href="#training-partners" aria-label="Permalink to &quot;Training Partners&quot;">​</a></h3><ul><li></li><li></li><li></li></ul><h3 id="today-s-intention" tabindex="-1">Today&#39;s Intention <a class="header-anchor" href="#today-s-intention" aria-label="Permalink to &quot;Today&#39;s Intention&quot;">​</a></h3><p>(What was my main focus for this session?)</p><hr><h3 id="technische-praktijk" tabindex="-1">Technische praktijk <a class="header-anchor" href="#technische-praktijk" aria-label="Permalink to &quot;Technische praktijk&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Geoefende vaardigheid</th><th>Herhalingen/tijd</th><th>Succespercentage</th><th>Opmerkingen</th></tr></thead><tbody><tr><td><strong>Wijzen</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Opnames</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Terreinlezen</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Opnameselectie</strong></td><td></td><td></td><td></td></tr></tbody></table><p>Wat werkte goed?</p><ol><li></li><li></li><li></li></ol><p>Wat kan er verbeterd worden?</p><ol><li></li><li></li><li></li></ol><h3 id="kerninzicht" tabindex="-1">Kerninzicht <a class="header-anchor" href="#kerninzicht" aria-label="Permalink to &quot;Kerninzicht&quot;">​</a></h3><p>(Eén belangrijke les die we vandaag hebben geleerd)</p><hr><h3 id="mental-game" tabindex="-1">Mental Game <a class="header-anchor" href="#mental-game" aria-label="Permalink to &quot;Mental Game&quot;">​</a></h3><p><strong>Energy Level (1-10):</strong> _____ <strong>Focus Quality (1-10):</strong> _____ <strong>Confidence (1-10):</strong> _____</p><p><strong>Mental Challenges Today:</strong></p><p><strong>How I Handled Them:</strong></p><p><strong>Mental Technique Practiced:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Other: ________</li></ul><hr><h3 id="fysieke-conditie" tabindex="-1">Fysieke conditie <a class="header-anchor" href="#fysieke-conditie" aria-label="Permalink to &quot;Fysieke conditie&quot;">​</a></h3><p><strong>Lichaamsgevoel (1-10):</strong> _____ <strong>Pijn/ongemak:</strong> _____ <strong>Vermoeidheidsniveau (1-10):</strong> _____</p><p><strong>Fysieke kenmerken:</strong></p><hr><h3 id="tomorrow-s-focus" tabindex="-1">Tomorrow&#39;s Focus <a class="header-anchor" href="#tomorrow-s-focus" aria-label="Permalink to &quot;Tomorrow&#39;s Focus&quot;">​</a></h3><p>(Based on today, what will I work on next session?)</p><hr><h2 id="sjabloon-voor-wedstrijd-competitie-inschrijving" tabindex="-1">Sjabloon voor wedstrijd-/competitie-inschrijving <a class="header-anchor" href="#sjabloon-voor-wedstrijd-competitie-inschrijving" aria-label="Permalink to &quot;Sjabloon voor wedstrijd-/competitie-inschrijving&quot;">​</a></h2><h3 id="kopieer-dit-gedeelte-voor-elke-wedstrijd" tabindex="-1">Kopieer dit gedeelte voor elke wedstrijd <a class="header-anchor" href="#kopieer-dit-gedeelte-voor-elke-wedstrijd" aria-label="Permalink to &quot;Kopieer dit gedeelte voor elke wedstrijd&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Tournament:</strong> ________ <strong>Format:</strong> Triples / Doubles / Singles <strong>Team:</strong> ________</p><h3 id="pre-competition" tabindex="-1">Pre-Competition <a class="header-anchor" href="#pre-competition" aria-label="Permalink to &quot;Pre-Competition&quot;">​</a></h3><p><strong>Sleep Quality (1-10):</strong> _____ <strong>Nutrition:</strong> _____ <strong>Mental State (1-10):</strong> _____ <strong>Physical Warm-up:</strong> Yes / No <strong>Mental Warm-up:</strong> Yes / No</p><hr><h3 id="wedstrijdresultaten" tabindex="-1">Wedstrijdresultaten <a class="header-anchor" href="#wedstrijdresultaten" aria-label="Permalink to &quot;Wedstrijdresultaten&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ronde</th><th>Tegenstander</th><th>Score</th><th>Resultaat</th><th>Belangrijkste momenten</th></tr></thead><tbody><tr><td><strong>1</strong></td><td></td><td></td><td>W / L</td><td></td></tr><tr><td><strong>2</strong></td><td></td><td></td><td>W / L</td><td></td></tr><tr><td><strong>3</strong></td><td></td><td></td><td>W / L</td><td></td></tr><tr><td><strong>4</strong></td><td></td><td></td><td>W / L</td><td></td></tr></tbody></table><p><strong>Eindpositie:</strong> _____</p><hr><h3 id="performance-analysis" tabindex="-1">Performance Analysis <a class="header-anchor" href="#performance-analysis" aria-label="Permalink to &quot;Performance Analysis&quot;">​</a></h3><p><strong>Technical Performance (1-10):</strong> _____ <strong>Mental Performance (1-10):</strong> _____ <strong>Tactical Decisions (1-10):</strong> _____ <strong>Team Communication (1-10):</strong> _____</p><h3 id="what-i-did-well" tabindex="-1">What I Did Well <a class="header-anchor" href="#what-i-did-well" aria-label="Permalink to &quot;What I Did Well&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="what-cost-me-points" tabindex="-1">What Cost Me Points <a class="header-anchor" href="#what-cost-me-points" aria-label="Permalink to &quot;What Cost Me Points&quot;">​</a></h3><ol><li></li><li></li></ol><h2 id="monthly-summary-template" tabindex="-1">Monthly Summary Template <a class="header-anchor" href="#monthly-summary-template" aria-label="Permalink to &quot;Monthly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Maand:</strong> ________ <strong>Jaar:</strong> ________</p><h3 id="maandelijkse-statistieken" tabindex="-1">Maandelijkse statistieken <a class="header-anchor" href="#maandelijkse-statistieken" aria-label="Permalink to &quot;Maandelijkse statistieken&quot;">​</a></h3><p><strong>Totaal aantal trainingsuren:</strong> _____ <strong>Totaal aantal sessies:</strong> _____ <strong>Deelgenomen wedstrijden:</strong> _____ <strong>Winstpercentage:</strong> _____%</p><h3 id="technische-vooruitgang" tabindex="-1">Technische vooruitgang <a class="header-anchor" href="#technische-vooruitgang" aria-label="Permalink to &quot;Technische vooruitgang&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vaardigheid</th><th>Begin van de maand</th><th>Einde van de maand</th><th>Verbetering</th></tr></thead><tbody><tr><td><strong>Aanwijsnauwkeurigheid</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Schietconsistentie</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Terreinaanpassing</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Opnameselectie</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="voortgang-van-het-mentale-spel" tabindex="-1">Voortgang van het mentale spel <a class="header-anchor" href="#voortgang-van-het-mentale-spel" aria-label="Permalink to &quot;Voortgang van het mentale spel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Gebied</th><th>Begin van de maand</th><th>Einde van de maand</th><th>Verbetering</th></tr></thead><tbody><tr><td><strong>Drukbeheersing</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Focus op kwaliteit</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Zelfvertrouwen</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Gebruik van Inner Coach</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="maandelijkse-hoogtepunten" tabindex="-1">Maandelijkse hoogtepunten <a class="header-anchor" href="#maandelijkse-hoogtepunten" aria-label="Permalink to &quot;Maandelijkse hoogtepunten&quot;">​</a></h3><p><strong>Beste trainingssessie:</strong></p><p><strong>Beste wedstrijdprestatie:</strong></p><p><strong>Grootste doorbraak:</strong></p><p><strong>Belangrijkste leerervaring:</strong></p><h3 id="uitdagingen-overwonnen" tabindex="-1">Uitdagingen overwonnen <a class="header-anchor" href="#uitdagingen-overwonnen" aria-label="Permalink to &quot;Uitdagingen overwonnen&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="lopende-uitdagingen" tabindex="-1">Lopende uitdagingen <a class="header-anchor" href="#lopende-uitdagingen" aria-label="Permalink to &quot;Lopende uitdagingen&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="prioriteiten-voor-volgende-maand" tabindex="-1">Prioriteiten voor volgende maand <a class="header-anchor" href="#prioriteiten-voor-volgende-maand" aria-label="Permalink to &quot;Prioriteiten voor volgende maand&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr><h2 id="specific-practice-tracking-templates" tabindex="-1">Specific Practice Tracking Templates <a class="header-anchor" href="#specific-practice-tracking-templates" aria-label="Permalink to &quot;Specific Practice Tracking Templates&quot;">​</a></h2><h3 id="pointing-practice-log" tabindex="-1">Pointing Practice Log <a class="header-anchor" href="#pointing-practice-log" aria-label="Permalink to &quot;Pointing Practice Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Distance</th><th>Terrain</th><th>Attempts</th><th>Within 10cm</th><th>Within 20cm</th><th>Within 50cm</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions:</strong></p><ul><li>Track pointing accuracy at different distances (6m, 7m, 8m, 9m, 10m)</li><li>Record terrain type (hard, medium, soft)</li><li>Count successes in each distance range</li><li>Calculate success rate over time</li></ul><hr><h3 id="schietoefenlogboek" tabindex="-1">Schietoefenlogboek <a class="header-anchor" href="#schietoefenlogboek" aria-label="Permalink to &quot;Schietoefenlogboek&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datum</th><th>Doeltype</th><th>Afstand</th><th>Pogingen</th><th>Directe treffers</th><th>Carreau</th><th>Verplaatsing</th><th>Opmerkingen</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Doelgroepen:</strong></p><ul><li>Statische bal</li><li>Bal tegen cochonnet</li><li>Bal in cluster</li><li>Bewegend doel (geavanceerd)</li></ul><hr><h3 id="mental-training-log" tabindex="-1">Mental Training Log <a class="header-anchor" href="#mental-training-log" aria-label="Permalink to &quot;Mental Training Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Technique Practiced</th><th>Duration</th><th>Situation</th><th>Effectiveness (1-10)</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Techniques:</strong></p><ul><li>3-Breath Reset</li><li>Inner Coach Reframe</li><li>Visualization</li><li>Mindfulness Practice</li><li>Pre-shot Routine</li><li>Pressure Simulation</li></ul><hr><h2 id="snelle-dagelijkse-invoer-vereenvoudigd" tabindex="-1">Snelle dagelijkse invoer (vereenvoudigd) <a class="header-anchor" href="#snelle-dagelijkse-invoer-vereenvoudigd" aria-label="Permalink to &quot;Snelle dagelijkse invoer (vereenvoudigd)&quot;">​</a></h2><h3 id="voor-drukke-dagen-kopieer-deze-minimalistische-sjabloon" tabindex="-1">Voor drukke dagen - Kopieer deze minimalistische sjabloon <a class="header-anchor" href="#voor-drukke-dagen-kopieer-deze-minimalistische-sjabloon" aria-label="Permalink to &quot;Voor drukke dagen - Kopieer deze minimalistische sjabloon&quot;">​</a></h3><hr><p><strong>Date:</strong> ________</p><p><strong>Trained:</strong> Yes / No <strong>Duration:</strong> _____ min <strong>Focus:</strong> ________ <strong>Energy (1-10):</strong> _____ <strong>Quality (1-10):</strong> _____</p><p><strong>One Win:</strong></p><p><strong>One Learning:</strong></p><p><strong>Tomorrow&#39;s Focus:</strong></p><hr><h2 id="reflectievragen" tabindex="-1">Reflectievragen <a class="header-anchor" href="#reflectievragen" aria-label="Permalink to &quot;Reflectievragen&quot;">​</a></h2><p>Gebruik deze vragen om je dagboeknotities te verdiepen:</p><h3 id="na-de-training" tabindex="-1">Na de training <a class="header-anchor" href="#na-de-training" aria-label="Permalink to &quot;Na de training&quot;">​</a></h3><ol><li>Wat heeft me vandaag verrast?</li><li>Wanneer voelde ik me het meest zelfverzekerd?</li><li>Wanneer heb ik het moeilijk gehad? Waarom?</li><li>Wat zou ik anders doen?</li><li>Waar ben ik dankbaar voor in deze sessie?</li></ol><h3 id="na-de-wedstrijd" tabindex="-1">Na de wedstrijd <a class="header-anchor" href="#na-de-wedstrijd" aria-label="Permalink to &quot;Na de wedstrijd&quot;">​</a></h3><ol><li>Wat heb ik vandaag over mezelf geleerd?</li><li>Hoe ging ik om met druk?</li><li>Wat zou mijn innerlijke coach zeggen over mijn prestaties?</li><li>Wat ga ik anders doen naar aanleiding van vandaag?</li><li>Waar ben ik trots op, ongeacht het resultaat?</li></ol><h3 id="wekelijkse-reflectie" tabindex="-1">Wekelijkse reflectie <a class="header-anchor" href="#wekelijkse-reflectie" aria-label="Permalink to &quot;Wekelijkse reflectie&quot;">​</a></h3><ol><li>Welk patroon zie ik in mijn werkwijze?</li><li>Oefen ik de dingen waar ik tijdens de wedstrijd moeite mee heb?</li><li>Gaat mijn mentale spel vooruit?</li><li>Geniet ik van het proces?</li><li>Wat moet er volgende week veranderen?</li></ol><h3 id="maandelijkse-reflectie" tabindex="-1">Maandelijkse reflectie <a class="header-anchor" href="#maandelijkse-reflectie" aria-label="Permalink to &quot;Maandelijkse reflectie&quot;">​</a></h3><ol><li>Ben ik dichter bij mijn doelen dan vorige maand?</li><li>Wat werkt er goed in mijn trainingsaanpak?</li><li>Wat werkt er niet?</li><li>Moet ik mijn doelen bijstellen?</li><li>Wat wil ik me van deze maand herinneren?</li></ol><hr><h2 id="tips-for-effective-diary-keeping" tabindex="-1">Tips for Effective Diary Keeping <a class="header-anchor" href="#tips-for-effective-diary-keeping" aria-label="Permalink to &quot;Tips for Effective Diary Keeping&quot;">​</a></h2><h3 id="_1-write-immediately-after-training" tabindex="-1">1. Write Immediately After Training <a class="header-anchor" href="#_1-write-immediately-after-training" aria-label="Permalink to &quot;1. Write Immediately After Training&quot;">​</a></h3><p><strong>Why:</strong> Details are fresh, emotions are real, insights are clear</p><p><strong>How:</strong> Keep diary in your bag, set 10 minutes aside after each session</p><h3 id="_2-be-honest-not-perfect" tabindex="-1">2. Be Honest, Not Perfect <a class="header-anchor" href="#_2-be-honest-not-perfect" aria-label="Permalink to &quot;2. Be Honest, Not Perfect&quot;">​</a></h3><p><strong>Don&#39;t:</strong> Write what you think you should write <strong>Do:</strong> Write what actually happened and how you really felt</p><h3 id="_3-focus-on-process-not-just-results" tabindex="-1">3. Focus on Process, Not Just Results <a class="header-anchor" href="#_3-focus-on-process-not-just-results" aria-label="Permalink to &quot;3. Focus on Process, Not Just Results&quot;">​</a></h3><p><strong>Don&#39;t:</strong> &quot;Missed 7 out of 10 shots - terrible&quot; <strong>Do:</strong> &quot;Missed 7 out of 10 shots - noticed I was rushing my routine, will slow down next time&quot;</p><h3 id="_4-look-for-patterns" tabindex="-1">4. Look for Patterns <a class="header-anchor" href="#_4-look-for-patterns" aria-label="Permalink to &quot;4. Look for Patterns&quot;">​</a></h3><p>Review your diary weekly to spot:</p><ul><li>Recurring technical issues</li><li>Mental game patterns</li><li>Energy/performance correlations</li><li>What conditions you perform best in</li></ul><h3 id="_5-celebrate-progress" tabindex="-1">5. Celebrate Progress <a class="header-anchor" href="#_5-celebrate-progress" aria-label="Permalink to &quot;5. Celebrate Progress&quot;">​</a></h3><p><strong>Every month:</strong> Read entries from 3 months ago <strong>Notice:</strong> How much you&#39;ve improved <strong>Acknowledge:</strong> The work you&#39;ve put in</p><hr><h2 id="digitale-versus-papieren-agenda" tabindex="-1">Digitale versus papieren agenda <a class="header-anchor" href="#digitale-versus-papieren-agenda" aria-label="Permalink to &quot;Digitale versus papieren agenda&quot;">​</a></h2><h3 id="digitaal-google-docs-sheets-notion-apps" tabindex="-1">Digitaal (Google Docs/Sheets, Notion, Apps) <a class="header-anchor" href="#digitaal-google-docs-sheets-notion-apps" aria-label="Permalink to &quot;Digitaal (Google Docs/Sheets, Notion, Apps)&quot;">​</a></h3><p><strong>Voordelen:</strong></p><ul><li>Gemakkelijk om eerdere berichten te doorzoeken</li><li>Foto&#39;s/video&#39;s toevoegen mogelijk</li><li>Automatische datumstempels</li><li>Kan gedeeld worden met de coach</li><li>Altijd telefonisch bereikbaar</li></ul><p><strong>Nadelen:</strong></p><ul><li>Schermtijd</li><li>Kan onpersoonlijk aanvoelen</li><li>Afleiding door meldingen</li></ul><p><strong>Ideaal voor:</strong> Gedetailleerde statistische tracking, analyse van patronen op lange termijn</p><h3 id="papier-notitieboekje-geprinte-sjablonen" tabindex="-1">Papier (notitieboekje, geprinte sjablonen) <a class="header-anchor" href="#papier-notitieboekje-geprinte-sjablonen" aria-label="Permalink to &quot;Papier (notitieboekje, geprinte sjablonen)&quot;">​</a></h3><p><strong>Voordelen:</strong></p><ul><li>Tastbare, persoonlijke verbinding</li><li>Geen afleiding</li><li>Diagrammen zijn gemakkelijk te tekenen</li><li>Bevredigend ritueel</li><li>Beter voor reflectie</li></ul><p><strong>Nadelen:</strong></p><ul><li>Kan notitieboekje kwijtraken</li><li>Het is moeilijk om oude berichten te doorzoeken</li><li>Kan niet gemakkelijk gedeeld worden</li></ul><p><strong>Ideaal voor:</strong> Dagelijkse reflecties, aantekeningen direct na de training</p><p><strong>Aanbeveling:</strong> Hybride aanpak - papier voor dagelijkse aantekeningen, digitaal voor maandelijkse samenvattingen en statistieken</p><hr><h2 id="sample-entries" tabindex="-1">Sample Entries <a class="header-anchor" href="#sample-entries" aria-label="Permalink to &quot;Sample Entries&quot;">​</a></h2><h3 id="example-good-training-entry" tabindex="-1">Example: Good Training Entry <a class="header-anchor" href="#example-good-training-entry" aria-label="Permalink to &quot;Example: Good Training Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 15, 2024 <strong>Duration:</strong> 90 minutes <strong>Location:</strong> Club terrain <strong>Terrain:</strong> Hard <strong>Weather:</strong> Sunny, light wind</p><p><strong>Today&#39;s Intention:</strong> Improve pointing accuracy at 8m</p><p><strong>Technical Practice:</strong></p><ul><li>Pointing at 8m: 30 attempts, 18 within 20cm (60%)</li><li>Noticed I&#39;m more accurate when I take 3 breaths before throwing</li><li>Struggled when wind picked up - need to adjust for wind better</li></ul><p><strong>What Worked Well:</strong></p><ol><li>Pre-shot routine was consistent</li><li>Stayed calm after misses</li><li>Adjusted grip for hard terrain</li></ol><p><strong>Key Insight:</strong> My accuracy drops when I rush. Slowing down by 2 seconds improves success rate significantly.</p><p><strong>Mental Game:</strong></p><ul><li>Energy: 8/10</li><li>Focus: 7/10</li><li>Used Inner Coach after 3 bad throws - helped me reset</li></ul><p><strong>Tomorrow&#39;s Focus:</strong> Practice pointing in windy conditions, maintain slow routine</p></details><h3 id="example-good-competition-entry" tabindex="-1">Example: Good Competition Entry <a class="header-anchor" href="#example-good-competition-entry" aria-label="Permalink to &quot;Example: Good Competition Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 20, 2024 <strong>Tournament:</strong> Regional Championship <strong>Format:</strong> Triples <strong>Final Placement:</strong> 5th of 16 teams</p><p><strong>Performance Analysis:</strong></p><ul><li>Technical: 7/10 - Pointing was solid, shooting was inconsistent</li><li>Mental: 8/10 - Stayed calm under pressure</li><li>Tactical: 6/10 - Made one bad decision in semi-final</li></ul><p><strong>Best Moment:</strong> Carreau in quarter-final to win 13-12</p><p><strong>Toughest Moment:</strong> Semi-final, 11-11, rushed a shot and missed badly</p><p><strong>Key Learning:</strong> When score is tight, I need to slow down even more, not speed up. My Inner Critic tried to take over (&quot;Don&#39;t mess this up!&quot;) but I caught it and used Inner Coach instead (&quot;You&#39;ve made this shot 100 times, trust your routine&quot;).</p><p><strong>For Next Competition:</strong> Practice pressure situations in training - simulate 11-11 scenarios</p></details><hr><h2 id="gerelateerde-bronnen" tabindex="-1">Gerelateerde bronnen <a class="header-anchor" href="#gerelateerde-bronnen" aria-label="Permalink to &quot;Gerelateerde bronnen&quot;">​</a></h2><ul><li><a href="/en/goal-template">Sjabloon voor het stellen van doelen</a> - Stel je verbeteringsdoelen vast en houd ze bij.</li><li><a href="/en/workshop">Workshop</a> - Groepssessies over mentale training en reflectie</li><li><a href="/en/training-session">Trainingssessie</a> - Gestructureerde oefening met leeftijdsgenoten</li><li><a href="/en/education/mental-strength">Mentale kracht</a> - Bouw mentale veerkracht op</li><li><a href="/en/education/mindfulness">Mindfulness</a> - Ontwikkel bewustzijn en focus</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to diary keeping? Start here:</strong></p><p><strong>Week 1:</strong> Use Quick Daily Entry (5 minutes after each session) <strong>Week 2:</strong> Add one reflection prompt per entry <strong>Week 3:</strong> Try full Daily Training Entry <strong>Week 4:</strong> Do first Weekly Summary</p><p><strong>After one month:</strong> Add Monthly Summary and specific practice logs</p><hr><p>::: Waarschuwing: Veelvoorkomende dagboekfouten</p><ol><li><strong>Te gedetailleerd</strong> - 30 minuten schrijven en dan na een week stoppen.</li><li><strong>Te vaag</strong> - &quot;Vandaag getraind, ging wel&quot; helpt je niet om te verbeteren.</li><li><strong>Alleen mislukkingen registreren</strong> - Vier ook de successen!</li><li><strong>Nooit recensies lezen</strong> - De kracht zit hem in het lezen van eerdere berichten.</li><li><strong>Te lang wachten</strong> - Schrijf binnen 30 minuten na afloop. :::</li></ol><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Evernote</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Daily Training Entry Template</li><li>Competition/Match Entry Template</li><li>Weekly Summary Template</li></ol><hr><p><strong>Hoogste moment:</strong></p><p><strong>Moeilijkste moment:</strong></p><p><strong>Mijn reactie:</strong></p><hr><h3 id="mental-game-in-competition" tabindex="-1">Mental Game in Competition <a class="header-anchor" href="#mental-game-in-competition" aria-label="Permalink to &quot;Mental Game in Competition&quot;">​</a></h3><p><strong>Pressure Situations:</strong></p><p><strong>How I Managed Pressure:</strong></p><p><strong>Inner Critic Activity (1-10):</strong> _____ <strong>Inner Coach Activity (1-10):</strong> _____</p><p><strong>Mental Techniques Used:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Routine Consistency</li><li>[ ] Other: ________</li></ul><hr><p>Belangrijkste leerpunten</p><p><strong>Technische specificaties:</strong></p><p><strong>Tactisch:</strong></p><p><strong>Mentaal:</strong></p><p><strong>Voor de volgende wedstrijd:</strong></p><hr><h2 id="weekly-summary-template" tabindex="-1">Weekly Summary Template <a class="header-anchor" href="#weekly-summary-template" aria-label="Permalink to &quot;Weekly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Week van:</strong> ________</p><h3 id="trainingsoverzicht" tabindex="-1">Trainingsoverzicht <a class="header-anchor" href="#trainingsoverzicht" aria-label="Permalink to &quot;Trainingsoverzicht&quot;">​</a></h3><p><strong>Totaal aantal trainingsuren:</strong> _____ <strong>Aantal sessies:</strong> _____ <strong>Wedstrijdtijden:</strong> _____ <strong>Mentale training:</strong> _____ minuten <strong>Fysieke training:</strong> _____ sessies</p><h3 id="wekelijkse-voortgang" tabindex="-1">Wekelijkse voortgang <a class="header-anchor" href="#wekelijkse-voortgang" aria-label="Permalink to &quot;Wekelijkse voortgang&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Doelgebied</th><th>Doelstelling</th><th>Werkelijk</th><th>Voortgang</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="de-overwinningen-van-deze-week" tabindex="-1">De overwinningen van deze week <a class="header-anchor" href="#de-overwinningen-van-deze-week" aria-label="Permalink to &quot;De overwinningen van deze week&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="uitdagingen-van-deze-week" tabindex="-1">Uitdagingen van deze week <a class="header-anchor" href="#uitdagingen-van-deze-week" aria-label="Permalink to &quot;Uitdagingen van deze week&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="patroonherkenning" tabindex="-1">Patroonherkenning <a class="header-anchor" href="#patroonherkenning" aria-label="Permalink to &quot;Patroonherkenning&quot;">​</a></h3><p>(Welke patronen zie ik in mijn oefening/optreden?)</p><h3 id="focus-van-volgende-week" tabindex="-1">Focus van volgende week <a class="header-anchor" href="#focus-van-volgende-week" aria-label="Permalink to &quot;Focus van volgende week&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr>',196)])])}]]);export{i as __pageData,r as default};
